/// A comment line that opens with a generator's marker: `// Generated by`,
/// `// Generated using SwiftGen`, `// DO NOT EDIT.`. Prose that merely
/// mentions generated code, and `///` doc comments, do not count. Computed:
/// a `Regex` is not `Sendable`, so it cannot be a stored global.
var generatedMarkerPattern: Regex<Substring> {
  #/^\s*(?:\/\/(?!\/)|\/\*+|\*)\s*(?:GENERATED CODE|Generated code|Generated by|Generated using|DO NOT EDIT)\b/#
}
